// === Tab: mySketch ===
// "painted hills" by garabatospr

// color palette

var colors   =  ["#f2f2f2","#666666","#333333","#000000","#ffffff"];

// set weights for each color 

// red, blue, and white dominates 

var weights  = [10,1,10,1,6,3];             

// scale of the vector field 
// smaller values => bigger structures  
// bigger values  ==> smaller structures 

var myScale =3;

// number of drawing agents 

var nAgents = 4000;

let agent = [];

function setup() {
  createCanvas(1920, 1080);
  colorMode(HSB, 360, 100, 100);
  strokeCap(ROUND);

  background(0);

  for(let i=0;i < nAgents;i++)
  {
    agent.push(new Agent());
  }

}

function draw() {

  for(let i=0;i < agent.length;i++)
  {
    agent[i].update();
  }


}

// select random colors with weights from palette 

function myRandom(colors,weights)
{ 
    let tt = 0;
    let sum = 0;

    //for(let i=0;i < colors.length; i++)
    //{
    //  sum += weights[i];
    //}

    let rr = random(0,sum);

    for(let j=0;j < weights.length;j++)
    {

      if (weights[j] >= rr)
      {
        return colors[j];
      }
        rr -= weights[j];
    }

    return tt;
 }



// paintining agent 


class Agent {
  constructor()
  {
    this.p     = createVector(1,height/2 + randomGaussian()*400);

    this.pOld  = createVector(this.p.x,this.p.y);

    this.step  = 1;

    let temp   =  myRandom(colors,weights);

    this.color = color(hue(temp) + randomGaussian()*20,
                       saturation(temp) + randomGaussian()*10,
                       brightness(temp) - 10,random(10,90));

    this.strokeWidth = random(1,5);
  }

  update() {

    this.p.x += vector_field(this.p.x,this.p.y).x*this.step;
    this.p.y += vector_field(this.p.x,this.p.y).y*this.step;

    strokeWeight(this.strokeWidth);
    stroke(this.color);
    line(this.pOld.x,this.pOld.y,this.p.x,this.p.y);

    this.pOld.set(this.p);

  }

}

// vector field function 
// the painting agents follow the flow defined 
// by this function 


function vector_field(x,y) {

  x = map(x,0,width,-myScale,myScale);
  y = map(y,0,height,-myScale,myScale);

  let k1 = 5;
  let k2 = 3;

  let u = sin(k1*y) + cos(k2*y);
  let v = sin(k2*x) - cos(k1*x);

  // litle trick to move from left to right 

  if (u <= 0) 
  {
      u = -u;
   }  

  return createVector(u,v);
}


// function to select 

function myRandom(colors,weights)
{ 
    var tt = 0;
    var sum = 0;

    for(let i=0;i < colors.length; i++)
    {
      sum += weights[i];
    }

    var rr = random(0,sum);

    for(let j=0;j < weights.length;j++)
    {

      if (weights[j] >= rr)
      {
        return colors[j];
      }
        rr -= weights[j];
    }

    return tt;
 }

